<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Algorithm Visualizer</title>
<style>
  body{margin:0;font-family:sans-serif;background:#121212;color:#e0e0e0;}
  #controls{padding:10px;text-align:center;}
  button{margin:5px;padding:10px 20px;background:#1f1f1f;border:none;color:white;cursor:pointer;}
  button:hover{background:#333;}
  #bars{display:flex;height:80vh;margin:10px auto;width:90%;max-width:800px;align-items:flex-end;}
  .bar{flex:1;margin:0 2px;background:#4caf50;transition:height 0.3s,background 0.3s;}
</style>
</head>
<body>

<div id="controls">
  <button id="reset">Reset</button>
  <button id="shuffle">Shuffle</button>
  <button id="sort">Sort</button>
</div>
<div id="bars"></div>

<script>
(function(){
const N=50; // number of bars
let arr=[];
let stepIndex=0;
let sortedFlag=false;

// Create initial array (sorted)
function initArray(){
  arr = Array.from({length:N},(_,i)=>i+1);
}
initArray();

// Render bars
function render(){
  const container=document.getElementById('bars');
  container.innerHTML='';
  const max=Math.max(...arr);
  for(let v of arr){
    const bar=document.createElement('div');
    bar.className='bar';
    bar.style.height=(v/max*100)+'%';
    container.appendChild(bar);
  }
}

// Shuffle array
function shuffleArray(){
  for(let i=arr.length-1;i>0;i--){
    let j=Math.floor(Math.random()*(i+1));
    [arr[i],arr[j]]=[arr[j],arr[i]];
  }
  stepIndex=0;
  sortedFlag=false;
  render();
}

// Bubble sort state machine
function sortStep(){
  if(sortedFlag) return true;
  const n=arr.length;
  // Each pass moves largest to end; we track i index within a pass
  for(let k=stepIndex;k<n-1;k++){
    if(arr[k]>arr[k+1]){
      [arr[k],arr[k+1]]=[arr[k+1],arr[k]];
      stepIndex=k+1;
      render();
      return false;
    }
  }
  // No swap in this pass -> sorted
  sortedFlag=true;
  render();
  return true;
}

// Check if array is sorted ascending
function isSorted(){
  for(let i=0;i<arr.length-1;i++){
    if(arr[i]>arr[i+1]) return false;
  }
  return true;
}

// API exposed on window.viz
window.viz={
  array:()=>arr.slice(),
  setArray:(a)=>{arr=a.slice();stepIndex=0;sortedFlag=isSorted();render();},
  sortStep,
  sorted:isSorted
};

// Button event listeners
document.getElementById('reset').onclick=()=>{
  initArray();
  render();
};
document.getElementById('shuffle').onclick=()=>shuffleArray();
document.getElementById('sort').onclick=()=>{
  const interval=setInterval(()=>{
    if(sortStep()){
      clearInterval(interval);
    }
  },200); // adjust speed
};

render();
})();
</script>
</body>
</html>
